package com.drogaria.backend.controller;
import com.drogaria.backend.dto.ServicoRequest; import com.drogaria.backend.dto.ServicoResponse; import com.drogaria.backend.service.ServicoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/servico") public class ServicoController { private final ServicoService s; public ServicoController(ServicoService s){this.s=s;} @GetMapping public List<ServicoResponse> listar(){return s.listar();} @GetMapping("/{id}") public ServicoResponse buscar(@PathVariable Integer id){return s.buscar(id);} @PostMapping public ResponseEntity<ServicoResponse> salvar(@Valid @RequestBody ServicoRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{id}") public ServicoResponse atualizar(@PathVariable Integer id,@Valid @RequestBody ServicoRequest r){return s.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }